package com.example.southindianplanner;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;import java.util.*;

public class MainActivity extends Activity {
 int day=0, page=0; LinearLayout root,body,nav; TextView header; SharedPreferences prefs;
 final String[][] meals={
 {"Idli + sambar","Rice, keerai kootu, carrot poriyal","Dosa + omelette"},
 {"Ven pongal + chutney","Lemon rice + potato roast","Curd rice"},
 {"Rava upma + chutney","Rice, sambar, beans poriyal","Chapati + kurma"},
 {"Dosa + sambar","Tomato rice + egg","Idli + chutney"},
 {"Puttu + kadala curry","Rice, rasam, cabbage poriyal","Dosa + chutney"},
 {"Poori + masala","Rice, keerai kootu, poriyal","Chapati + kurma"},
 {"Idiyappam + coconut milk","Rice, sambar, beetroot poriyal","Vegetable dosa"}
 };
 final String[] grocery={"Rice — 2 kg","Idli / dosa batter — 1 kg","Toor dal — 500 g","Onion — 500 g","Tomato — 500 g","Carrot — 250 g","Beans — 250 g","Greens — 1 bunch","Potato — 500 g","Curd — 500 g","Eggs — 6","Coconut — 2"};
 final String[] recipeNames={"Idli","Sambar","Lemon rice","Tomato rice","Vegetable dosa","Keerai kootu","Ven pongal","Rava upma"};
 int ink=Color.rgb(35,45,39),green=Color.rgb(35,115,76),pale=Color.rgb(237,246,239),muted=Color.rgb(105,115,108);
 @Override public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("planner",0);day=prefs.getInt("day",0);getWindow().setStatusBarColor(Color.rgb(250,252,249));getWindow().setNavigationBarColor(Color.WHITE);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=0)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},10);build();}
 GradientDrawable bg(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(radius);return d;}
 TextView text(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);if(bold)t.setTypeface(null,Typeface.BOLD);return t;}
 LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}
 void build(){root=column();root.setBackgroundColor(Color.rgb(250,252,249));root.setPadding(20,16,20,8);setContentView(root);LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);TextView brand=text("🥥  OORU MEALS",18,green,true);top.addView(brand,new LinearLayout.LayoutParams(0,-2,1));TextView date=text("30-DAY PLAN  •  2 ADULTS",11,muted,true);top.addView(date);root.addView(top);header=text("",25,ink,true);LinearLayout.LayoutParams hp=new LinearLayout.LayoutParams(-1,-2);hp.topMargin=18;hp.bottomMargin=12;root.addView(header,hp);ScrollView sc=new ScrollView(this);body=column();sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));nav=new LinearLayout(this);nav.setPadding(0,8,0,4);String[] tabs={"Home","Calendar","Shopping","Recipes","Settings"};for(int i=0;i<tabs.length;i++){final int p=i;TextView b=text(tabs[i],11,i==page?green:muted,true);b.setGravity(Gravity.CENTER);b.setPadding(2,12,2,12);nav.addView(b,new LinearLayout.LayoutParams(0,-2,1));b.setOnClickListener(v->{page=p;render();});}root.addView(nav);render();}
 void card(String title,String sub){LinearLayout c=column();c.setPadding(16,14,16,14);c.setBackground(bg(Color.WHITE,22));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=12;body.addView(c,lp);c.addView(text(title,17,ink,true));TextView d=text(sub,14,muted,false);d.setPadding(0,6,0,0);c.addView(d);}
 void button(String label,Runnable action){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setTextColor(Color.WHITE);b.setBackground(bg(green,18));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=10;body.addView(b,p);b.setOnClickListener(v->action.run());}
 void render(){body.removeAllViews();header.setText(new String[]{"Good day 👋","Meal calendar","Grocery basket","Recipe book","Preferences"}[page]);for(int i=0;i<nav.getChildCount();i++){TextView t=(TextView)nav.getChildAt(i);t.setTextColor(i==page?green:muted);}
 if(page==0){card("TODAY  •  DAY "+(day+1),mealText(day));card("TOMORROW'S MENU",mealText((day+1)%30));button("View full 30-day calendar",()->{page=1;render();});button("Open grocery checklist",()->{page=2;render();});card("DAILY REMINDER","Set a 7:00 PM notification to check tomorrow's menu and shopping list.");button("Enable 7:00 PM reminder",()->schedule());card("YOUR PROGRESS",checkedCount()+" of "+grocery.length+" grocery items checked");}
 if(page==1){card("30 DAYS • MEAL OVERVIEW","Choose a day to view its breakfast, lunch and dinner.");for(int i=0;i<30;i++){final int d=i;LinearLayout row=new LinearLayout(this);row.setPadding(14,13,14,13);row.setGravity(Gravity.CENTER_VERTICAL);row.setBackground(bg(Color.WHITE,16));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=7;body.addView(row,lp);TextView a=text("DAY "+(i+1),14,green,true);row.addView(a,new LinearLayout.LayoutParams(75,-2));TextView b=text(mealText(i),13,ink,false);row.addView(b,new LinearLayout.LayoutParams(0,-2,1));row.setOnClickListener(v->{day=d;prefs.edit().putInt("day",day).apply();page=0;render();});}}
 if(page==2){card("SHOPPING LIST","For 2 adults • Tick items as you buy them. Your ticks are saved.");for(int i=0;i<grocery.length;i++){final int n=i;CheckBox cb=new CheckBox(this);cb.setText(grocery[i]);cb.setTextSize(15);cb.setTextColor(ink);cb.setButtonTintList(android.content.res.ColorStateList.valueOf(green));cb.setChecked(prefs.getBoolean("g"+i,false));cb.setOnCheckedChangeListener((v,on)->prefs.edit().putBoolean("g"+n,on).apply());body.addView(cb);}button("Reset shopping checklist",()->{for(int i=0;i<grocery.length;i++)prefs.edit().putBoolean("g"+i,false).apply();render();});card("SHOPPING PROGRESS",checkedCount()+" / "+grocery.length+" items purchased");}
 if(page==3){card("SIMPLE RECIPE COLLECTION","Starter recipe names. Detailed quantities and steps will be added from your chosen recipes.");for(String s:recipeNames)card("🍲  "+s,"Tap to plan this dish. Recipe instructions are not yet verified from your PDF.");}
 if(page==4){card("HOUSEHOLD SETTINGS","Current plan serves 2 adults. Menu and grocery quantities are sample defaults.");card("REMINDERS","Daily reminder at 7:00 PM. Android notification permission must be allowed.");button("Enable / reset 7:00 PM reminder",()->schedule());button("Turn off reminder",()->{Intent i=new Intent(this,ReminderReceiver.class);PendingIntent p=PendingIntent.getBroadcast(this,1,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);((AlarmManager)getSystemService(ALARM_SERVICE)).cancel(p);Toast.makeText(this,"Reminder disabled",Toast.LENGTH_SHORT).show();});card("ABOUT VERSION 2","Ooru Meals • Offline starter app. Your data stays on this phone.");}
 }
 String mealText(int d){String[] m=meals[d%7];return "Breakfast: "+m[0]+"\nLunch: "+m[1]+"\nDinner: "+m[2];}
 int checkedCount(){int n=0;for(int i=0;i<grocery.length;i++)if(prefs.getBoolean("g"+i,false))n++;return n;}
 void schedule(){AlarmManager a=(AlarmManager)getSystemService(ALARM_SERVICE);Intent i=new Intent(this,ReminderReceiver.class);PendingIntent p=PendingIntent.getBroadcast(this,1,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Calendar c=Calendar.getInstance();c.set(Calendar.HOUR_OF_DAY,19);c.set(Calendar.MINUTE,0);c.set(Calendar.SECOND,0);if(c.getTimeInMillis()<=System.currentTimeMillis())c.add(Calendar.DATE,1);a.setInexactRepeating(AlarmManager.RTC_WAKEUP,c.getTimeInMillis(),AlarmManager.INTERVAL_DAY,p);Toast.makeText(this,"Daily 7:00 PM reminder enabled",Toast.LENGTH_LONG).show();}
}